import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.DHSXpJLs.js";const f=JSON.parse('{"title":"创建第一个项目","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-project.md","filePath":"guide/first-project.md","lastUpdated":1790779354000}'),o={name:"guide/first-project.md"};function l(n,e,c,d,s,g){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="创建第一个项目" tabindex="-1">创建第一个项目 <a class="header-anchor" href="#创建第一个项目" aria-label="Permalink to &quot;创建第一个项目&quot;">​</a></h1><p>平台的用户入口是项目。模型由 AI agent 在项目会话里生成，用户不上传文件。</p><h2 id="操作流程" tabindex="-1">操作流程 <a class="header-anchor" href="#操作流程" aria-label="Permalink to &quot;操作流程&quot;">​</a></h2><ol><li><strong>新建项目</strong>。在首页点「新建空白项目（AI 建模）」，填标题，选项目类型： <ul><li><code>ifc</code>：AI 生成 IFC 模型。建项目时就初始化一个骨架模型。</li><li><code>cad</code>：AI 生成 DXF 图纸，agent 会话内按需初始化。</li><li><code>cad-&gt;ifc</code>：先出图再转 IFC 的完整链路。</li><li>类型创建后不可改，换管线要删项目重建。</li></ul></li><li><strong>对话建模</strong>。进入项目会话，在右侧 AI 对话栏用自然语言描述需求。agent 按项目类型派发子 agent 生成模型，过程中能看到工具调用卡片和中间预览。</li><li><strong>审查</strong>。模型出现在项目模型列表里，点击进入查看器。IFC 走三维查看器，DXF 走二维画布。界面细节见<a href="/SourceAEC/guide/interface">界面使用</a>。</li><li><strong>编辑</strong>。选中构件点定位脚本，跳到脚本对应行。改参数或改代码，沙箱验证后保存大版本。</li><li><strong>对比版本</strong>。工具栏的 Diff 选择 base 和 target 做语义对比。</li></ol><p>第 4、5 步的概念与操作见<a href="/SourceAEC/guide/editing">编辑与版本</a>。没有配置 LLM 时，chat agent 会退到离线模式：界面流程都能走通，但不会有真正的智能回复，配置方法见<a href="/SourceAEC/guide/configuration">配置说明</a>。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>出问题了：<a href="/SourceAEC/guide/troubleshooting">故障排查</a>。</li><li>想让外部 AI agent 也来改模型：<a href="/SourceAEC/reference/ai">AI 接入</a>。</li><li>想把整套搬到服务器上：<a href="/SourceAEC/guide/deploy">生产部署与运维</a>。</li></ul>',7)])])}const h=a(o,[["render",l]]);export{f as __pageData,h as default};
